const I = (ru, en, r, cat, th, att, noteRu, noteEn, extra) => ({
  ru,
  en,
  r,
  cat,
  th,
  ...(att ? { att } : null),
  note: { ru: noteRu, en: noteEn },
  ...extra,
});
